/// What may follow the slash after a utility (ex. the `50` in `bg-red-500/50`).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Modifier {
  /// Nothing.
  None,
  /// Only an arbitrary value (ex. `ease-in/[50%]`).
  Arbitrary,
  /// An opacity (ex. `bg-red-500/50`).
  Opacity,
  /// A line height (ex. `text-sm/6`).
  LineHeight,
  /// Anything (ex. `bg-linear-to-r/oklch`).
  Any,
}

