/// The root of utilities that are followed by a value (ex. `text` in `text-red-500`).
pub struct UtilityRoot {
  pub name: &'static str,
  /// Position and modifier for most of the named values (ex. `border-red-500`).
  pub default: (u16, Modifier),
  /// Position and modifier for a number (ex. `border-3`).
  pub number: (u16, Modifier),
  /// Position and modifier for an arbitrary length (ex. `text-[14px]`).
  pub arbitrary_length: (u16, Modifier),
  /// Position and modifier for an arbitrary color (ex. `text-[#fff]`).
  pub arbitrary_color: (u16, Modifier),
  /// The kinds of values that are valid, which is a combination of the `VALUE_` constants.
  pub value_kinds: u8,
  /// The other values that are valid.
  pub values: &'static [&'static str],
}

/// A whole number (ex. `z-17`).
pub const VALUE_INTEGER: u8 = 1;
/// A number that's a multiple of 0.25 (ex. `p-1.5`).
pub const VALUE_QUARTER: u8 = 2;
/// Any number with a decimal (ex. `opacity-2.3`).
pub const VALUE_DECIMAL: u8 = 4;
/// A fraction (ex. `w-3/7`).
pub const VALUE_FRACTION: u8 = 8;
/// A percentage (ex. `from-10%`).
pub const VALUE_PERCENTAGE: u8 = 16;
/// One of `COLORS` (ex. `bg-red-500`).
pub const VALUE_COLOR: u8 = 32;
/// An arbitrary value (ex. `w-[3px]` or `w-(--width)`).
pub const VALUE_ARBITRARY: u8 = 64;

