#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum VariantKind {
  /// Doesn't have a value (ex. `hover`).
  Static,
  /// May be followed by a value (ex. `data` in `data-active`).
  Functional,
  /// Is followed by another variant (ex. `group` in `group-hover`).
  Compound,
}

/// How variants that have the same position are ordered.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum VariantValueOrder {
  /// By their root then value.
  None,
  /// From the smallest value to the largest (ex. the width of the breakpoint in `min-md`).
  Ascending,
  /// From the largest value to the smallest (ex. the width of the breakpoint in `max-md`).
  Descending,
}

/// What the value of a variant may be other than an arbitrary one.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum VariantValues {
  /// Anything (ex. `data-active`).
  Any,
  /// A whole number (ex. `nth-3`).
  Integer,
  /// One that's in `VARIANT_VALUES` or the theme (ex. `max-md`).
  Known,
}

